with u as (select id from auth.users order by created_at limit 1)
insert into public.place_segments (id, user_id, name, from_id, to_id, distance_km, d_plus, d_minus, notes)
select v.id, u.id, v.name, v.from_id, v.to_id, v.distance_km, v.d_plus, v.d_minus, v.notes from u, (values
  ('point', '', 'point-20', 'point-22', null::numeric, 200::int, 200::int, '')
) as v(id, name, from_id, to_id, distance_km, d_plus, d_minus, notes)
on conflict (user_id, id) do update set name=excluded.name, from_id=excluded.from_id, to_id=excluded.to_id,
  distance_km=excluded.distance_km, d_plus=excluded.d_plus, d_minus=excluded.d_minus, notes=excluded.notes;

